/**
 * Cascade behind `ProjectService.archiveProject`. Only issues that are still
 * live are stamped; rows archived earlier keep their original `archivedAt`
 * (the retention sweep keys off that date). The returned count is the number
 * of issues this call archived, which is what the audit log and the
 * issues-used meter both subtract.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

